func inorderTraversal(root *TreeNode) []int {
	res := []int{}
	var dfs func(root *TreeNode)
	dfs = func(root *TreeNode) {
		if root == nil {
			return
		}
		// 按照 左-打印-右 的方式遍历
		dfs(root.Left)
		res = append(res, root.Val)
		dfs(root.Right)
	}
	dfs(root)
	return res
}

func inorderTraversal(root *TreeNode) []int {
	res := []int{}
	stack := []*TreeNode{}
	for len(stack) > 0 || root != nil {
		// 不断往左子树方向走，每走一次就将当前节点保存到栈中
		// 这是模拟递归的调用
		if root != nil {
			stack = append(stack, root)
			root = root.Left
		} else {
			// 当前节点为空，说明左边走到头了，从栈中弹出节点并保存
			// 然后转向右边节点，继续上面整个过程
			tmp := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			res = append(res, tmp.Val)
			root = tmp.Right
		}
	}
	return res
}

func inorderTraversal(root *TreeNode) []int {
	res := []int{}
	pre := (*TreeNode)(nil)
	for root != nil {
		// 如果左节点不为空，就将当前节点连带右子树全部挂到
		// 左节点的最右子树下面
		if root.Left != nil {
			pre = root.Left
			for pre.Right != nil {
				pre = pre.Right
			}
			pre.Right = root
			// 将 root 指向 root 的 left
			tmp := root
			root = root.Left
			tmp.Left = nil
		} else {
			// 左子树为空，则打印这个节点，并向右边遍历
			res = append(res, root.Val)
			root = root.Right
		}
	}
	return res
}

